-- pos-location: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.bays (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    max_concurrent_vehicles integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    last_modified_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    location_id uuid NOT NULL,
    bay_type character varying(50) NOT NULL,
    status character varying(50) NOT NULL,
    name character varying(255) NOT NULL,
    normalized_name character varying(255) NOT NULL,
    service_capability_ids text,
    skill_requirement_ids text,
    version bigint DEFAULT 0 NOT NULL
);

CREATE TABLE public.event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.ext_people_contact_person (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    person_id uuid NOT NULL,
    first_name character varying(255),
    last_name character varying(255),
    primary_email character varying(255),
    contact_points text,
    aggregate_version bigint NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.ext_storage_location_on_hand (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    storage_location_id uuid NOT NULL,
    on_hand_quantity numeric(19,4) NOT NULL,
    aggregate_version bigint NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.location (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    check_in_buffer_minutes integer,
    cleanup_buffer_minutes integer,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone,
    version bigint,
    default_quarantine_location_id uuid,
    default_staging_location_id uuid,
    geographical_location_id uuid,
    id uuid NOT NULL,
    location_type_id uuid,
    address_line1 character varying(255),
    address_line2 character varying(255),
    city character varying(255),
    code character varying(255),
    country character varying(255),
    holiday_closures text,
    hr_location_id character varying(255),
    mailing_address character varying(255),
    name character varying(255),
    normalized_name character varying(255),
    operating_hours text,
    postal_code character varying(255),
    state character varying(255),
    status character varying(255),
    timezone character varying(255),
    responsible_person_id uuid,
    phone_number character varying(50)
);

CREATE TABLE public.location_parent (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    child_id uuid,
    id uuid NOT NULL,
    parent_id uuid,
    parent_type character varying(255) NOT NULL,
    CONSTRAINT location_parent_parent_type_check CHECK (((parent_type)::text = ANY (ARRAY[('HOME_OFFICE'::character varying)::text, ('HEADQUARTERS'::character varying)::text, ('REGION'::character varying)::text, ('DISTRICT'::character varying)::text, ('PHYSICAL'::character varying)::text, ('ORGANIZATIONAL'::character varying)::text, ('FINANCIAL'::character varying)::text, ('SHIPPING'::character varying)::text])))
);

CREATE TABLE public.location_type (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    description character varying(255),
    name character varying(255) NOT NULL
);

CREATE TABLE public.mobile_unit_capabilities (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    mobile_unit_id uuid NOT NULL,
    service_capability_id uuid
);

CREATE TABLE public.mobile_unit_coverage_rules (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    max_distance numeric(10,2),
    priority integer NOT NULL,
    valid_from date,
    valid_to date,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    mobile_unit_id uuid NOT NULL,
    service_area_id uuid,
    rule_type character varying(20)
);

CREATE TABLE public.mobile_units (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    base_location_id uuid,
    created_by uuid,
    id uuid NOT NULL,
    travel_buffer_policy_id uuid,
    updated_by uuid,
    status character varying(20) NOT NULL,
    name character varying(255) NOT NULL,
    notes character varying(255),
    version bigint DEFAULT 0 NOT NULL
);

CREATE TABLE public.processed_events (
    event_id character varying(36) NOT NULL,
    owner character varying(64) NOT NULL,
    processed_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.service_area_postal_codes (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    country_code character varying(2) NOT NULL,
    service_area_id uuid NOT NULL,
    postal_code character varying(20) NOT NULL
);

CREATE TABLE public.service_areas (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    active boolean NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    id uuid NOT NULL,
    description character varying(255),
    name character varying(255) NOT NULL
);

CREATE TABLE public.service_location_capabilities (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    active boolean NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    code character varying(100) NOT NULL,
    name character varying(255) NOT NULL
);

CREATE TABLE public.storage_location (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    parent_storage_location_id uuid,
    site_id uuid NOT NULL,
    status character varying(20) NOT NULL,
    type character varying(50) NOT NULL,
    barcode character varying(255),
    capacity text,
    name character varying(255) NOT NULL,
    temperature text,
    version bigint DEFAULT 0 NOT NULL,
    storage_category_code character varying(30),
    hazard_containment boolean DEFAULT false NOT NULL,
    allow_new_product character varying(30) DEFAULT 'MIXED'::character varying NOT NULL,
    CONSTRAINT storage_location_allow_new_product_check CHECK (((allow_new_product)::text = ANY ((ARRAY['MIXED'::character varying, 'SAME_PRODUCT_ONLY'::character varying, 'EMPTY_ONLY'::character varying])::text[]))),
    CONSTRAINT storage_location_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('MAINTENANCE'::character varying)::text, ('QUARANTINED'::character varying)::text]))),
    CONSTRAINT storage_location_storage_category_code_check CHECK (((storage_category_code IS NULL) OR ((storage_category_code)::text = ANY ((ARRAY['TIRE_RACK'::character varying, 'OIL_STORAGE'::character varying, 'BATTERY_RACK'::character varying, 'SMALL_PARTS_BIN'::character varying, 'BULK_FLOOR'::character varying, 'STAGING'::character varying, 'QUARANTINE'::character varying, 'GENERAL'::character varying])::text[])))),
    CONSTRAINT storage_location_type_check CHECK (((type)::text = ANY (ARRAY[('FLOOR'::character varying)::text, ('SHELF'::character varying)::text, ('BIN'::character varying)::text, ('CAGE'::character varying)::text, ('TRUCK'::character varying)::text])))
);

CREATE TABLE public.travel_buffer_policies (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    buffer_value numeric(10,2),
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    id uuid NOT NULL,
    buffer_type character varying(30),
    name character varying(255) NOT NULL,
    notes character varying(255)
);

